function toolIcon(id){const paths={'image-compressor':'M8 3H3v5M16 21h5v-5M3 3l7 7m11 11-7-7M16 3h5v5M3 16v5h5M21 3l-7 7M3 21l7-7','image-resizer':'M4 9V4h5m6 0h5v5m0 6v5h-5M9 20H4v-5M4 4l5 5m11 11-5-5','image-converter':'M4 7h15l-4-4m4 4-4 4M20 17H5l4 4m-4-4 4-4','image-cropper':'M7 3v14h14M3 7h14v14','profit-calculator':'M4 19h16M6 15l5-5 4 3 5-8M16 5h4v4','discount-calculator':'M6 18 18 6M8 6a2 2 0 1 0 0 .01M16 16a2 2 0 1 0 0 .01','target-size-compressor':'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4'};return '<svg viewBox="0 0 24 24" width="23" height="23" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[id]+'"/></svg>'}
function card(t){return `<a class="tool-card" href="${toolLink(t)}" data-group="${t.group}"><div class="card-top"><span class="tool-icon">${toolIcon(t.id)}</span><span class="tag">${t.tag}</span></div><h3>${t.name}</h3><p>${t.desc}</p><div class="tool-demonstration" aria-hidden="true">${t.group==='image'?'<div class="image-demo '+t.id+'"><img src="/assets/seller-still-life.webp" alt="" loading="lazy"><span>'+(t.id==='image-resizer'?'1200 × 1200':t.id==='image-converter'?'JPG → WebP':t.id==='image-cropper'?'The right frame':t.id==='target-size-compressor'?'Set your size limit':'Lighter. Ready to go.')+'</span></div>':'<div class="number-demo"><span>'+(t.id==='profit-calculator'?'Price − costs':'Your next promotion')+'</span><strong>'+(t.id==='profit-calculator'?'Know your margin.':'Make every % count.')+'</strong><div class="demo-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div>'}</div><span class="card-link">Open tool <span>↗</span></span></a>`}
function home(){content.innerHTML=`<div class="container"><section class="hero premium-hero"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> THE INDEPENDENT SELLER’S TOOLKIT</div><h1>Less busywork.<br><em>More possibility.</em></h1><p class="intro">Beautiful images. Clearer numbers.<br>Everything you need to get your next listing out into the world.</p><div class="hero-actions"><a class="button orange" href="#tools">Explore the toolkit <span>↗</span></a><a class="text-link" href="/tools/profit-calculator/">Know your margins <span>→</span></a></div><div class="hero-assurance"><span>7 free tools</span><span>No account needed</span><span>Images stay private</span></div></div><div class="studio-window"><div class="studio-top"><div><span class="window-dot"></span><span class="window-dot"></span><span class="window-dot"></span></div><span>MANGLO IMAGE STUDIO</span><span class="studio-live">Interactive preview</span></div><div class="studio-tabs" role="group" aria-label="Preview image formats"><button type="button" class="studio-tab selected" data-demo-format="image/webp" aria-pressed="true">WebP</button><button type="button" class="studio-tab" data-demo-format="image/jpeg" aria-pressed="false">JPG</button><button type="button" class="studio-tab" data-demo-format="image/png" aria-pressed="false">PNG</button><a href="/tools/image-converter/">Use your image ↗</a></div><div class="studio-body"><div class="studio-photo"><img src="/assets/seller-still-life.webp" alt="Sample product photo used by the interactive image export preview" width="1536" height="1024" fetchpriority="high"><span class="photo-caption">SAMPLE PRODUCT IMAGE</span><span class="photo-corner">↗</span></div><div class="studio-controls"><div class="studio-file"><span class="studio-file-icon">${toolIcon('image-converter')}</span><div><b id="demo-filename">product-image.webp</b><small>Local processing · no upload</small></div><span class="file-tick">✓</span></div><div class="studio-quality"><label for="demo-quality">Export quality <span id="demo-quality-value">80%</span></label><input id="demo-quality" type="range" min="10" max="100" value="80"></div><button class="studio-export" id="demo-download" type="button">Download sample <span>↓</span></button><p id="demo-status" role="status">Try an export, then bring your own images.</p></div></div><div class="studio-bottom"><span><i></i> Your files. Your device.</span><span>JPG / PNG / WEBP</span></div></div></section><div class="benefits"><span><i>01</i> Prepare your photos</span><span><i>02</i> Find your margin</span><span><i>03</i> Publish with confidence</span><a href="/about/">Made for independent business ↗</a></div><section class="section" id="tools"><div class="section-top"><div><div class="eyebrow">LESS FRICTION. MORE FORWARD.</div><h2>Your next task, simplified.</h2><p>Pick a tool. Make a little progress.</p></div><div class="filters" aria-label="Filter tools"><button class="filter active" data-filter="all" aria-pressed="true">All tools</button><button class="filter" data-filter="image" aria-pressed="false">Image tools</button><button class="filter" data-filter="calculator" aria-pressed="false">Calculators</button></div></div><div class="tool-grid">${tools.map(card).join('')}</div></section><section class="feature-band"><div class="feature-copy"><div class="eyebrow">SMALL BUSINESS. BIG ENERGY.</div><h2>You have enough<br>on your to-do list.</h2><p>Your tools should make it shorter. Manglo brings the everyday essentials into one calm, simple space.</p><a class="button light" style="color:white;border-color:#6a7a69;margin-top:10px" href="/about/">Meet Manglo <span>↗</span></a></div><div class="feature-detail"><div><span class="number">01</span><section><b>Open it. Use it. Done.</b><p>No account setup or complicated dashboards.</p></section></div><div><span class="number">02</span><section><b>Your photos stay yours.</b><p>Image processing happens right in your browser.</p></section></div><div><span class="number">03</span><section><b>Clarity comes standard.</b><p>Useful previews, clear calculations and downloadable results.</p></section></div></div></section><section id="guides"><div class="section-top"><div><div class="eyebrow">A LITTLE KNOW-HOW</div><h2>Good things to know.</h2></div><p>Practical reads for your next move.</p></div><div class="guides">${guides.map(g=>`<a class="guide-card" href="/guides/${g.id}/"><div class="guide-art"><img src="${g.id==='prepare-product-images'?'/assets/photography-studio.webp':g.id==='calculate-selling-profit'?'/assets/seller-desk.webp':'/assets/seller-still-life.webp'}" alt="${g.id==='prepare-product-images'?'A small product photography studio':g.id==='calculate-selling-profit'?'Calculator and notebook on a seller workspace':'Product photograph for comparing image formats'}" loading="lazy" width="768" height="512">${g.id==='jpg-png-webp'?'<span class="format-pills"><span>JPG</span><span>PNG</span><span>WebP</span></span>':''}</div><div><div class="eyebrow">${g.type}</div><h3>${g.title}</h3><p>${g.time} <span style="float:right">↗</span></p></div></a>`).join('')}</div></section><section class="section faq"><h2>A few things, answered.</h2><details><summary>Are Manglo tools really free?</summary><p>Yes. Every tool currently listed is free, with no account or subscription required. If we introduce a paid feature in the future, we will clearly label it.</p></details><details><summary>Do you upload or store my images?</summary><p>No. These image tools use your browser to process the files you choose. Images are not sent to a Manglo server. Closing or reloading the page clears your workspace.</p></details><details><summary>Can I use the tools on my phone?</summary><p>Yes, in a modern browser. Large photos may take longer on mobile devices. Each image is limited to 20 MB and 40 million pixels to protect browser memory.</p></details><details><summary>Are the calculators specific to a marketplace?</summary><p>No. Enter your own fees and costs. The results are estimates based on your inputs, not official marketplace quotes or tax advice.</p></details></section><div class="end-note">Made for the people making things happen.</div></div>`;
setupHeroPreview();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('[data-group]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.group!==b.dataset.filter)}));}

function setupHeroPreview(){let format='image/webp';const quality=document.querySelector('#demo-quality'),status=document.querySelector('#demo-status'),download=document.querySelector('#demo-download');document.querySelectorAll('[data-demo-format]').forEach(button=>button.addEventListener('click',()=>{format=button.dataset.demoFormat;document.querySelectorAll('[data-demo-format]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});const ext={'image/webp':'webp','image/jpeg':'jpg','image/png':'png'}[format];document.querySelector('#demo-filename').textContent='product-image.'+ext;quality.disabled=format==='image/png';document.querySelector('#demo-quality-value').textContent=format==='image/png'?'Lossless':quality.value+'%';status.textContent='Choose your format, then download a real sample export.'}));quality.addEventListener('input',()=>document.querySelector('#demo-quality-value').textContent=quality.value+'%');download.addEventListener('click',async()=>{let bitmap;download.disabled=true;status.textContent='Preparing your sample export…';try{const response=await fetch('/assets/seller-still-life.webp');if(!response.ok)throw Error('Sample image unavailable.');bitmap=await createImageBitmap(await response.blob());const canvas=draw(bitmap,{white:format==='image/jpeg'});const blob=await encode(canvas,format,Number(quality.value)/100);const url=URL.createObjectURL(blob);currentURLs.push(url);const link=document.createElement('a');link.href=url;link.download=document.querySelector('#demo-filename').textContent;document.body.append(link);link.click();link.remove();status.textContent='Exported '+size(blob.size)+'. Ready to try your own?'}catch(error){status.textContent=error.message+' Open Image converter to try your own file.'}finally{bitmap?.close();download.disabled=false}});}

const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function setTitle(title){document.title=`${title} — Manglo`;document.querySelector('link[rel=canonical]').href=`https://manglo.shop${path==='/'?'/':path+'/'}`}
function toolPage(t){setTitle(t.name);const calculator=t.group==='calculator';content.innerHTML=`<div class="container"><div class="breadcrumb"><a href="/">Home</a> / <a href="/#tools">Tools</a> / ${t.name}</div><div class="page-heading"><div class="eyebrow">${calculator?'MAKE THE NUMBERS MAKE SENSE':'A LITTLE LESS IMAGE BUSYWORK'}</div><h1>${t.name}<span style="color:var(--orange)">.</span></h1><p>${t.desc} ${calculator?'Change any input to see your estimate update instantly.':'Free, private and processed on your device.'}</p></div><div id="tool-workspace"></div><section class="tool-explainer" id="how-it-works"></section></div>`;if(calculator)calculatorUI(t);else imageUI(t);}
function field(id,label,value,min=0,max='',step='any'){return `<label class="field" for="${id}">${label}<input id="${id}" type="number" value="${value}" min="${min}" ${max!==''?`max="${max}"`:''} step="${step}" required></label>`}
function calculatorUI(t){const profit=t.id==='profit-calculator';document.querySelector('#tool-workspace').innerHTML=`<div class="workspace"><form class="panel" id="calc-form"><h3>${profit?'Your selling numbers':'Plan your promotion'}</h3><label class="field">Currency<select id="currency"><option value="INR">INR · Indian rupee</option><option value="USD">USD · US dollar</option><option value="GBP">GBP · British pound</option><option value="EUR">EUR · Euro</option></select></label><div class="field-row">${field('price',profit?'Selling price':'Original price',1000)}${profit?field('cost','Product cost',400):field('discount','Discount (%)',20,0,100)}</div>${profit?`<div class="field-row">${field('fee','Platform / payment fee (%)',10,0,100)}${field('fixed','Fixed fee per order',10)}</div><div class="field-row">${field('shipping','Shipping you pay',80)}${field('other','Packaging + other costs',30)}</div>`:`${field('cost','Total cost per item (optional)',400)}<p class="help">Include product cost, shipping and fees here if you want a useful margin estimate.</p>`}<p class="help">Use the same currency for all amounts. Fees are applied to the selling price; taxes and marketplace-specific rules are not automatically included.</p></form><section class="panel" aria-label="Calculation results" aria-live="polite"><div id="calculation"></div><button class="button light full-width" id="copy-results" type="button">Copy estimate <span>↗</span></button><p class="copy-status" id="copy-status" role="status"></p></section></div>`;
let output='';const form=document.querySelector('#calc-form');function update(){const box=document.querySelector('#calculation');if(!form.checkValidity()){box.innerHTML='<p class="error">Enter valid, non-negative values. Percentages must be between 0 and 100.</p>';output='';return}const n=id=>Number(document.getElementById(id).value);const currency=document.querySelector('#currency').value;const fmt=v=>new Intl.NumberFormat('en',{style:'currency',currency}).format(v);const price=n('price'),cost=n('cost');const sale=profit?price:price*(1-n('discount')/100);const fees=profit?price*n('fee')/100+n('fixed'):0;const expenses=profit?cost+n('shipping')+n('other')+fees:cost;const net=sale-expenses;const margin=sale>0?`${(net/sale*100).toFixed(1)}%`:'Not defined';const row=(k,v)=>`<div class="result-row"><span>${k}</span><b>${v}</b></div>`;box.innerHTML=`<div class="result-hero"><small>${profit?'ESTIMATED PROFIT PER ORDER':'YOUR SALE PRICE'}</small><strong>${fmt(profit?net:sale)}</strong><small>${profit?(net<0?'This order makes a loss at these inputs.':'After the costs you entered.'):`Customer saves ${fmt(price-sale)}`}</small></div>${row('Selling price',fmt(sale))}${profit?row('Platform + fixed fees',fmt(fees)):row('Discount',n('discount')+'%')}${row('Total costs',fmt(expenses))}${row('Net profit',fmt(net))}${row('Profit margin',margin)}<p class="help">Margin = net profit ÷ selling price × 100. Estimate only; check your actual fee and tax obligations.</p>`;output=`Manglo estimate\nSelling price: ${fmt(sale)}\nTotal costs: ${fmt(expenses)}\nNet profit: ${fmt(net)}\nProfit margin: ${margin}`;}form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);update();document.querySelector('#copy-results').addEventListener('click',async()=>{const s=document.querySelector('#copy-status');if(!output){s.textContent='Correct the inputs first.';return}try{await navigator.clipboard.writeText(output);s.textContent='Estimate copied.'}catch{s.textContent='Clipboard unavailable. Select and copy the results above.'}});document.querySelector('#how-it-works').innerHTML=`<h2>Make a decision with the full picture.</h2><p>${profit?'Enter the amount your customer pays, the cost of your product, and every cost you absorb. Percentage fees are calculated on the selling price, then fixed fees, shipping and other expenses are subtracted.':'Enter your original price and a discount between 0 and 100%. The sale price is original price × (1 − discount ÷ 100). Add your complete per-item cost to see how much remains.'}</p><p>For example, an item selling for ₹1,000 with ₹400 product cost, ₹110 fees, ₹80 shipping and ₹30 packaging leaves ₹380, or a 38% margin. Refunds, advertising spend and tax may reduce that further. Include them in other costs where appropriate.</p><a class="button light" href="/guides/calculate-selling-profit/">Read the profit guide <span>↗</span></a>`;}
let currentURLs=[];
function imageUI(t){const resize=t.id==='image-resizer',crop=t.id==='image-cropper',target=t.id==='target-size-compressor',convert=t.id==='image-converter';document.querySelector('#tool-workspace').innerHTML=`<div class="workspace"><div class="panel"><label class="dropzone" id="dropzone"><span class="upload-icon">↥</span><strong>${crop?'Choose your image':'Drop your images here'}</strong><small>or select files from your device<br>JPG, PNG, WebP · up to 20 MB each · ${crop?'one image':'up to 10 images'}</small><input id="files" type="file" accept="image/jpeg,image/png,image/webp" ${crop?'':'multiple'}></label><img id="crop-preview" class="crop-preview hidden" alt="Source image preview"><div class="processing-status" id="image-status" role="status" aria-live="polite"></div><div id="results"></div></div><form class="panel settings" id="settings"><h3>${crop?'Frame your image':'Make it yours'}</h3>${resize?`<div class="field-row">${field('width','Width (px)',1200,1,10000,1)}${field('height','Height (px)',1200,1,10000,1)}</div><label class="field"><input id="keep-ratio" type="checkbox" checked> Preserve aspect ratio (fit within size)</label><p class="help">With aspect ratio preserved, these are maximum dimensions. Images are never enlarged in this mode.</p>`:''}${crop?`<label class="field">Aspect ratio<select id="ratio"><option value="1">Square · 1:1</option><option value="0.8">Portrait · 4:5</option><option value="1.7777777778">Landscape · 16:9</option><option value="0.5625">Story · 9:16</option></select></label><label class="field">Horizontal position<input id="crop-x" type="range" min="0" max="100" value="50"></label><label class="field">Vertical position<input id="crop-y" type="range" min="0" max="100" value="50"></label><p class="help">The preview below the upload area shows your crop. Move the sliders to keep your subject in frame.</p>`:''}<label class="field">Output format<select id="format"><option value="image/webp">WebP · smaller, modern</option><option value="image/jpeg">JPG · widely compatible</option><option value="image/png">PNG · lossless transparency</option></select></label>${target?field('target','Target size (KB)',200,5,20000,1):''}<label class="field">Quality <span id="quality-label">80%</span><input id="quality" type="range" min="10" max="100" value="80"></label><p class="help">${target?'We try lower quality and dimensions until the file fits. PNG is lossless, so dimensions may be reduced.':'Quality affects JPG and WebP. PNG is lossless. JPG replaces transparent areas with white.'}</p><button class="button orange full-width" id="process" type="submit">${crop?'Crop image':convert?'Convert images':resize?'Resize images':'Compress images'} <span>↗</span></button><button class="button light full-width" id="reset" style="margin-top:10px" type="button">Clear workspace</button><p class="help">▧ Your files never leave your device.</p></form></div>`;
let files=[],busy=false,previewURL=null,previewVersion=0;const input=document.querySelector('#files'),status=document.querySelector('#image-status'),results=document.querySelector('#results'),form=document.querySelector('#settings');const q=document.querySelector('#quality');q.addEventListener('input',()=>document.querySelector('#quality-label').textContent=q.value+'%');
function clearURLs(){currentURLs.forEach(u=>URL.revokeObjectURL(u));currentURLs=[];if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null}}
function choose(list){if(busy)return;files=Array.from(list).slice(0,crop?1:10);clearURLs();results.innerHTML='';status.classList.remove('error');status.textContent=files.length?`${files.length} image${files.length>1?'s':''} ready. Adjust your settings, then process.`:'';if(list.length>10)status.textContent+=' Only the first 10 files are selected.';if(crop)preview();}
input.addEventListener('change',()=>choose(input.files));const zone=document.querySelector('#dropzone');['dragenter','dragover'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.add('drag')}));['dragleave','drop'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.remove('drag')}));zone.addEventListener('drop',e=>choose(e.dataTransfer.files));
async function preview(){const version=++previewVersion;const img=document.querySelector('#crop-preview');if(!files.length){img.classList.add('hidden');return}let bitmap;try{bitmap=await loadImage(files[0]);const canvas=draw(bitmap,{crop:true,ratio:Number(document.querySelector('#ratio').value),x:Number(document.querySelector('#crop-x').value)/100,y:Number(document.querySelector('#crop-y').value)/100,maxPreview:600});const blob=await encode(canvas,'image/webp',.8);if(version!==previewVersion)return;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(blob);img.src=previewURL;img.classList.remove('hidden')}catch(e){status.textContent=e.message;status.classList.add('error')}finally{bitmap?.close()}}
if(crop)['ratio','crop-x','crop-y'].forEach(id=>document.getElementById(id).addEventListener('input',preview));
document.querySelector('#reset').addEventListener('click',()=>{if(busy)return;files=[];input.value='';results.innerHTML='';status.textContent='';clearURLs();++previewVersion;document.querySelector('#crop-preview').classList.add('hidden')});
form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;if(!files.length){status.textContent='Choose at least one image first.';status.classList.add('error');return}if(!form.reportValidity())return;busy=true;const button=document.querySelector('#process');button.disabled=true;button.textContent='Processing…';form.querySelectorAll('input,select').forEach(el=>el.disabled=true);input.disabled=true;currentURLs.forEach(u=>URL.revokeObjectURL(u));currentURLs=[];results.innerHTML='';status.classList.remove('error');let done=0;const format=document.querySelector('#format').value;for(const file of files){let bitmap;try{status.textContent=`Processing ${done+1} of ${files.length}…`;bitmap=await loadImage(file);let canvas=draw(bitmap,{resize,width:resize?Number(document.querySelector('#width').value):0,height:resize?Number(document.querySelector('#height').value):0,keep:resize&&document.querySelector('#keep-ratio').checked,crop,ratio:crop?Number(document.querySelector('#ratio').value):1,x:crop?Number(document.querySelector('#crop-x').value)/100:0,y:crop?Number(document.querySelector('#crop-y').value)/100:0,white:format==='image/jpeg'});let blob=await encode(canvas,format,Number(q.value)/100);if(target){const limit=Number(document.querySelector('#target').value)*1024;let quality=Number(q.value)/100;for(let attempt=0;blob.size>limit&&attempt<28;attempt++){if(format!=='image/png'&&quality>.15){quality=Math.max(.1,quality-.1)}else{const scale=Math.min(.85,Math.sqrt(limit/blob.size)*.95);const smaller=document.createElement('canvas');smaller.width=Math.max(1,Math.floor(canvas.width*scale));smaller.height=Math.max(1,Math.floor(canvas.height*scale));smaller.getContext('2d').drawImage(canvas,0,0,smaller.width,smaller.height);canvas=smaller}blob=await encode(canvas,format,quality)}if(blob.size>limit)throw Error('Could not meet the target. Try a larger size limit.');}
const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[blob.type];if(!ext)throw Error('Your browser does not support this output format.');const url=URL.createObjectURL(blob);currentURLs.push(url);const name=file.name.replace(/\.[^.]+$/,'')+'-manglo.'+ext;const saved=Math.round((1-blob.size/file.size)*100);const row=document.createElement('div');row.className='file-result';row.innerHTML=`<img src="${url}" alt="Processed image preview"><div class="file-info"><b>${escapeHTML(name)}</b><p>${size(file.size)} → ${size(blob.size)} · ${canvas.width} × ${canvas.height}<br>${saved>0?saved+'% smaller':saved<0?'Output is '+Math.abs(saved)+'% larger':'Similar file size'}</p></div><a class="download" href="${url}" download="${escapeHTML(name)}">Download ↓</a>`;results.append(row);done++}catch(error){const p=document.createElement('p');p.className='error processing-status';p.textContent=`${file.name}: ${error.message}`;results.append(p)}finally{bitmap?.close()}}
status.textContent=`${done} of ${files.length} image${files.length>1?'s':''} processed. Download your results below.`;busy=false;button.disabled=false;button.innerHTML=`Process ${crop?'image':'images'} <span>↗</span>`;form.querySelectorAll('input,select').forEach(el=>el.disabled=false);input.disabled=false;});
document.querySelector('#how-it-works').innerHTML=`<h2>From upload to ready-to-use.</h2><ol><li>Choose ${crop?'a product photo':'up to ten photos'} from your device. Supported inputs are JPG, PNG and WebP.</li><li>${crop?'Choose an aspect ratio and use the position sliders to frame your subject.':resize?'Set the maximum width and height. Keep aspect ratio enabled to avoid stretching.':target?'Enter your maximum size in KB. The tool may reduce quality and pixel dimensions to fit.':'Choose the output format and adjust quality to balance detail and file size.'}</li><li>Process your ${crop?'image':'images'}, inspect the preview and download the results.</li></ol><p>Keep an original copy. Re-encoding removes most file metadata and animated inputs become a single still image. Compression results vary: an already optimized photo may grow in size, especially when converted to PNG. Color and orientation can vary by browser; inspect downloaded results before publishing.</p><a class="button light" href="/guides/jpg-png-webp/">Choose the right format <span>↗</span></a>`;
}
const size=n=>n<1024*1024?`${(n/1024).toFixed(1)} KB`:`${(n/1024/1024).toFixed(2)} MB`;
async function loadImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use a JPG, PNG or WebP image.');if(file.size>20*1024*1024)throw Error('This image exceeds the 20 MB limit.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('This image exceeds the 40 megapixel limit.')}return bitmap}
function draw(bitmap,o){let sx=0,sy=0,sw=bitmap.width,sh=bitmap.height,w=sw,h=sh;if(o.crop){if(sw/sh>o.ratio){sw=sh*o.ratio;sx=(bitmap.width-sw)*o.x}else{sh=sw/o.ratio;sy=(bitmap.height-sh)*o.y}w=Math.max(1,Math.round(sw));h=Math.max(1,Math.round(sh))}if(o.resize){if(o.keep){const scale=Math.min(o.width/w,o.height/h,1);w=Math.max(1,Math.round(w*scale));h=Math.max(1,Math.round(h*scale))}else{w=o.width;h=o.height}}if(o.maxPreview){const scale=Math.min(1,o.maxPreview/Math.max(w,h));w=Math.max(1,Math.round(w*scale));h=Math.max(1,Math.round(h*scale))}if(w*h>40000000)throw Error('Output exceeds 40 megapixels. Choose smaller dimensions.');const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas is unavailable in this browser.');if(o.white){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h)}ctx.imageSmoothingQuality='high';ctx.drawImage(bitmap,sx,sy,sw,sh,0,0,w,h);return canvas}
function encode(canvas,type,quality){return new Promise((resolve,reject)=>canvas.toBlob(blob=>{if(!blob)reject(Error('Image encoding failed. Try a smaller image.'));else if(blob.type!==type)reject(Error('Your browser cannot export this format. Choose JPG or PNG.'));else resolve(blob)},type,quality))}
const articles={
'prepare-product-images':`<p>A product photo has two jobs: show the item accurately and help a buyer inspect the details. An enormous file does not automatically do either job better. Use this checklist to prepare images that are clear, consistent and easy to work with.</p><h2>1. Start with an honest, sharp original</h2><p>Clean the product and camera lens. Use soft daylight, a steady camera and a simple background. Photograph the actual item from several angles. Include a detail shot and a scale reference when dimensions are hard to judge. Avoid filters that change the color or hide wear.</p><h2>2. Leave room around the product</h2><p>A tight crop can cut off handles, straps or packaging when a marketplace shows a square thumbnail. Keep the full item comfortably inside the frame. Use consistent spacing across your catalog, and check the smallest thumbnail as well as the full-size photo.</p><div class="callout">Example workflow: keep your original, make a square crop, resize to 1,200 × 1,200 pixels, then export a WebP or JPG. This is a starting point, not a universal marketplace requirement.</div><h2>3. Match your destination</h2><p>Check the current image requirements of the platform where you sell. It may specify minimum dimensions, aspect ratio, file formats or background rules. Do not assume that a social post preset also works for a product listing.</p><h2>4. Resize before aggressively compressing</h2><p>If your source is 6,000 pixels wide but the destination displays a much smaller image, reducing dimensions can save more space than reducing quality alone. Avoid upscaling a small source: it creates more pixels without recovering detail.</p><h2>5. Compare the exported file</h2><p>Open the result at a realistic viewing size. Inspect labels, texture, seams and small lettering. If they look smeared, increase quality or retain more pixels. Keep file size low enough for the destination, but preserve details that affect a buying decision.</p><h2>Before you publish</h2><ul><li>Colors and condition are represented accurately.</li><li>The item is fully visible in the thumbnail.</li><li>Dimensions and file format fit the destination.</li><li>Text and fine details remain readable.</li><li>You have permission to use the images.</li></ul><a class="button" href="/tools/image-resizer/">Prepare your images ↗</a>`,
'calculate-selling-profit':`<p>Revenue is the money a customer pays. Profit is what remains after the costs of making that sale. Confusing the two makes it easy to run a busy shop that leaves very little money behind.</p><h2>Start with one order</h2><p>Write down your selling price, product cost, packaging, shipping you absorb, platform commission and payment fees. Add advertising or other per-order costs if you know them. Use a consistent approach to tax and check your obligations with a qualified adviser.</p><h2>A worked example</h2><table><tr><th>Item</th><th>Amount</th></tr><tr><td>Customer pays</td><td>₹1,000</td></tr><tr><td>Product cost</td><td>₹400</td></tr><tr><td>10% platform fee + ₹10 fixed fee</td><td>₹110</td></tr><tr><td>Shipping you pay</td><td>₹80</td></tr><tr><td>Packaging</td><td>₹30</td></tr><tr><th>Profit before other expenses and tax</th><th>₹380</th></tr></table><p>Total entered costs are ₹620. Subtracting them from ₹1,000 leaves ₹380. The profit margin is ₹380 ÷ ₹1,000 × 100 = 38%.</p><h2>Margin and markup are different</h2><p>Margin divides profit by selling price. Markup divides profit by cost. If something costs ₹600 and sells for ₹1,000, the profit is ₹400: a 40% margin and approximately 66.7% markup. Always check which measure a calculator or supplier is using.</p><h2>A discount changes more than revenue</h2><p>In the example above, a 20% discount brings the selling price to ₹800. A 10% fee plus ₹10 becomes ₹90. The other costs stay at ₹510, leaving ₹200 profit. The selling price fell 20%, but profit fell from ₹380 to ₹200—about 47.4%.</p><h2>Account for the costs that arrive later</h2><p>Returns, damaged goods, monthly subscriptions and unsold inventory may not appear in a single-order calculation. Review actual results regularly and allocate overhead reasonably. Manglo’s calculator is a planning aid; it does not replace bookkeeping or official marketplace statements.</p><a class="button" href="/tools/profit-calculator/">Check your numbers ↗</a>`,
'jpg-png-webp':`<p>The best image format depends on the image and where you plan to use it. A photograph, a transparent logo and a screenshot with small lettering have different needs. Here is a practical way to choose.</p><h2>JPG: a familiar choice for photos</h2><p>JPG is widely supported and is usually a practical option for product photography. It uses lossy compression: a lower quality setting reduces file size by discarding more information. It does not support transparency. Manglo fills transparent areas with white when exporting JPG.</p><h2>PNG: transparency and crisp graphics</h2><p>PNG supports transparency and lossless compression. It is useful for logos, interface screenshots and graphics with flat colors or sharp edges. A detailed photo exported as PNG can be much larger than a JPG. Moving the quality slider does not make PNG lossy.</p><h2>WebP: flexible, efficient delivery</h2><p>WebP supports transparency and can provide smaller files for many images. It is a useful choice for modern websites, but confirm that your listing platform, editor or upload form accepts it before converting a whole catalog.</p><table><tr><th>Situation</th><th>Starting choice</th></tr><tr><td>Product photo for broad compatibility</td><td>JPG</td></tr><tr><td>Transparent logo or sharp graphic</td><td>PNG</td></tr><tr><td>Website photo where WebP is supported</td><td>WebP</td></tr></table><h2>Compare using the same dimensions</h2><p>Export the same image at the same pixel size in two formats. Compare file size and visible detail, particularly around edges, gradients and text. A format name alone does not tell you which result will be smaller or clearer.</p><h2>Keep the source</h2><p>Repeatedly opening and saving a lossy image can introduce additional artifacts. Keep the original and create each export from that source. Manglo is intended for still images; animated inputs are exported as one frame, and most metadata is removed.</p><a class="button" href="/tools/image-converter/">Convert an image ↗</a>`
};
const pages={about:{title:'A little help for your next big thing.',body:`<p>Manglo is a collection of straightforward tools for independent sellers, creators and anyone getting a small business off the ground. Our aim is to make routine work easier: preparing a photo, checking a margin or planning a discount.</p><h2>Useful by design</h2><p>Every tool has one clear job. You can use the toolkit without creating an account, and the image tools process your files locally in your browser. We explain the assumptions behind calculations so you can judge whether they fit your business.</p><h2>Small tools, thoughtfully made</h2><p>The toolkit includes image compression, resizing, conversion and cropping, alongside profit and discount calculators. Our guides explain practical workflows using examples rather than promises of business success.</p><p>Have a suggestion or found an issue? Visit our <a href="/contact/">contact page</a>.</p><a class="button" href="/#tools">Find your next tool ↗</a>`},privacy:{title:'Privacy, in plain language.',body:`<p>Effective November 5, 2026. This policy describes the Manglo toolkit at manglo.shop.</p><h2>Your images</h2><p>Files selected in the image tools are processed in your browser. The tools do not upload those files to a Manglo server. Temporary previews remain in page memory until you clear the workspace, reload or close the page. Files you download are saved by your browser.</p><h2>Information collected by hosting</h2><p>Requests to load the website may be recorded by the hosting provider in standard server logs, including IP address, browser details, requested URL and request time. We do not ask you to create an account or enter payment details to use these tools.</p><h2>Fonts and external services</h2><p>This website requests fonts from Google Fonts. Those requests send standard connection information, including your IP address, to Google. Your browser may use a fallback font if the request is blocked.</p><h2>Cookies, analytics and advertising</h2><p>This version does not include advertising tags, analytics scripts or nonessential cookies. If advertising or analytics is introduced, this policy and any required consent controls must be updated before those services are enabled.</p><h2>Calculator inputs</h2><p>Calculator values are handled in page memory. Manglo does not send these values to a server or store them across visits. The copy button uses the browser clipboard only when you click it.</p><h2>Your choices and questions</h2><p>You can clear tool results at any time, close the page or block external font requests in your browser. To raise a privacy issue, email <a href="mailto:faikxbillion@gmail.com">faikxbillion@gmail.com</a>. If you email us, your message and address are handled by our email provider, Gmail, and used to respond to your request. Do not include passwords, private images or financial records.</p>`},terms:{title:'A few straightforward terms.',body:`<p>Effective November 5, 2026. By using Manglo.shop, you agree to these terms.</p><h2>Using the toolkit</h2><p>The tools are provided free of charge for lawful use. You are responsible for having the rights to any image you process and for checking that the resulting files meet your destination’s requirements.</p><h2>Check your results</h2><p>Image processing may change quality, metadata, dimensions, color or transparency. Keep original copies and inspect exports. Calculators provide estimates from the values you enter. They do not automatically account for every fee, tax, refund or business expense and are not financial or tax advice.</p><h2>Availability and limitations</h2><p>We aim to keep the tools useful, but provide them as available without a guarantee of uninterrupted operation or fitness for a specific purpose. Browser and device limitations may affect results. To the extent permitted by applicable law, Manglo is not responsible for losses resulting from reliance on tool output. Nothing here excludes rights that cannot legally be excluded.</p><h2>Changes and feedback</h2><p>Tools and these terms may change. The current effective date appears above. You can report problems through the <a href="/contact/">support contact</a>.</p>`},contact:{title:'Help make Manglo better.',body:`<p>Found a bug, have a tool suggestion or need to raise a privacy concern? Email us at <a href="mailto:faikxbillion@gmail.com">faikxbillion@gmail.com</a>.</p><a class="button" href="mailto:faikxbillion@gmail.com?subject=Manglo%20support">Email Manglo support ↗</a><p>Your email app will open so you can send your message. You can also copy the address above into your preferred email service.</p><h2>For a useful bug report</h2><ul><li>Tell us which tool you used.</li><li>Include your browser, device and the steps that caused the issue.</li><li>Describe what you expected and what happened instead.</li><li>For image issues, share the file format and dimensions rather than private files.</li></ul><p>Do not post passwords, private photos, customer details or financial records. There is no live chat or guaranteed response time.</p>`}}
function articlePage(title,body,eyebrow='THE MANGLO JOURNAL'){setTitle(title);content.innerHTML=`<article class="article"><div class="breadcrumb"><a href="/">Home</a> / ${eyebrow==='THE MANGLO JOURNAL'?'Seller guides':'Manglo'}</div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${body}</article>`;}
if(path==='/')home();else if(path.startsWith('/tools/')){const t=tools.find(t=>path===`/tools/${t.id}`);if(t)toolPage(t);else notFound()}else if(path.startsWith('/guides/')){const g=guides.find(g=>path===`/guides/${g.id}`);if(g)articlePage(g.title,'<img class="article-cover" src="'+(g.id==='prepare-product-images'?'/assets/photography-studio.webp':g.id==='calculate-selling-profit'?'/assets/seller-desk.webp':'/assets/seller-still-life.webp')+'" alt="Editorial illustration for this seller guide" width="1536" height="1024">'+articles[g.id]);else notFound()}else if(pages[path.slice(1)]){const p=pages[path.slice(1)];articlePage(p.title,p.body,'GOOD TO KNOW')}else notFound();
